"""MCP server "deck": expose make_deck and check_deck (criterion C) as MCP tools.

Stdout carries JSON-RPC only (rule: no other prints). Implementation lives in
.agents/skills/pptx/deck_tools.py so it is testable standalone too."""
from __future__ import annotations

import json
import sys

PROTOCOL_VERSION = "2025-06-18"
SERVER_INFO = {"name": "deck", "version": "1"}


def _log(msg: str) -> None:
    print(msg, file=sys.stderr, flush=True)


def _import_tools():
    import os
    root = os.environ.get("DECK_TOOLS_DIR") or os.path.abspath(os.path.join(os.getcwd(), ".agents", "skills", "pptx"))
    import importlib.util
    spec = importlib.util.spec_from_file_location("deck_tools", os.path.join(root, "deck_tools.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def make_deck(params: dict) -> tuple[str, bool]:
    mod = _import_tools()
    return mod.make_deck(params)


def check_deck(params: dict) -> tuple[str, bool]:
    mod = _import_tools()
    return mod.check_deck(params)


TOOLS = [
    {
        "name": "make_deck",
        "description": "Build a .pptx deck from a JSON spec of slides (title, agenda, cards, two-column, process, barchart, quote, closing) using the SKILL.md helper recipes. Writes the file under deck-lab/ and returns the path and slide count.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "name": {"type": "string", "description": "File name (without .pptx) under deck-lab/, e.g. 'a9_tieu.de'"},
                "slides": {"type": "array", "description": "Slide specs in order; see SKILL.md section 4 for the 8 kinds",
                           "items": {"type": "object",
                                     "properties": {
                                         "kind": {"type": "string", "enum": ["cover", "agenda", "cards", "twocol", "process", "barchart", "quote", "closing"],
                                                  "description": "Which of the 8 SKILL.md layouts"},
                                         "title": {"type": "string", "description": "Main heading text"},
                                         "subtitle": {"type": "string", "description": "Secondary line (cover) or source line (charts)"},
                                         "items": {"type": "array", "items": {"type": "string"},
                                                    "description": "Agenda rows or process step labels"},
                                         "cards": {"type": "array", "items": {"type": "array", "items": {"type": "string"}},
                                                     "description": "Cards: up to 3 rows of [big, label, description]"},
                                         "columns": {"type": "array", "items": {"type": "array", "items": {"type": "string"}},
                                                      "description": "Two-column comparison: [header, point1, point2, point3] x 2"},
                                         "data": {"type": "array", "items": {"type": "array", "items": {"type": "string"}},
                                                   "description": "Bar chart: [[label, value], ...]"}},
                                        "required": ["kind"]}},
                "accent": {"type": "string", "description": "Optional hex accent color, default #0B5ED7"},
            },
            "required": ["name", "slides"],
        },
    },
    {
        "name": "check_deck",
        "description": "Run the 8-point SKILL.md self-check (transitions, out-of-bounds, font floor, empty boxes, word cap, contrast, overflow estimate, overlap) on a .pptx; reports each defect with the slide number and the exact field/value that failed.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "path": {"type": "string", "description": "Path to the .pptx file to check"},
            },
            "required": ["path"],
        },
    },
]


def handle(msg: dict) -> dict | None:
    if "id" not in msg:
        return None
    method, params = msg.get("method"), msg.get("params") or {}
    try:
        if method == "initialize":
            result = {"protocolVersion": params.get("protocolVersion") or PROTOCOL_VERSION,
                      "capabilities": {"tools": {"listChanged": False}},
                      "serverInfo": SERVER_INFO}
        elif method == "ping":
            result = {}
        elif method == "tools/list":
            result = {"tools": TOOLS}
        elif method == "tools/call":
            name = str(params.get("name") or "")
            args = params.get("arguments") or {}
            if name == "make_deck":
                text, ok = make_deck(args)
            elif name == "check_deck":
                text, ok = check_deck(args)
            else:
                return {"jsonrpc": "2.0", "id": msg["id"],
                        "error": {"code": -32602, "message": f"unknown tool {name!r}"}}
            result = {"content": [{"type": "text", "text": text}], "isError": not ok}
        else:
            return {"jsonrpc": "2.0", "id": msg["id"],
                    "error": {"code": -32601, "message": f"method {method} not supported"}}
    except Exception as exc:  # surface as JSON-RPC error, keep stdout clean
        return {"jsonrpc": "2.0", "id": msg.get("id"),
                "error": {"code": -32603, "message": f"{type(exc).__name__}: {str(exc)[:300]}"}}
    return {"jsonrpc": "2.0", "id": msg["id"], "result": result}


def main() -> None:
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            reply = handle(json.loads(line))
        except ValueError:
            reply = {"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "parse error"}}
        if reply is not None:
            print(json.dumps(reply, ensure_ascii=False), flush=True)


if __name__ == "__main__":
    main()

"""make_deck / check_deck implementation (imported by deck_mcp_server.py and
usable standalone). Keeps SKILL.md helper recipes as the single source of truth."""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent.parent  # repo root
sys.path.insert(0, str(ROOT / ".agents" / "skills" / "pptx"))

import helpers  # noqa: E402
from helpers import (new_prs, fade, add_slide, txbox, slide_cover, slide_agenda,  # noqa: E402
                     slide_cards, slide_twocol, slide_process, slide_barchart,
                     slide_quote, slide_closing, BLUE, TEAL, MUTED, LINEC,
                     MSO_SHAPE_OVAL=None) if False else None  # placeholder, replaced below

# Import the concrete names we actually use (module attr access avoids a bad alias above)
from helpers import slide_title, source_line  # noqa: E402


def _hex_to_rgb(hexstr: str):
    from helpers import RGBColor
    h = hexstr.lstrip('#')
    return RGBColor(int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))


def make_deck(params: dict) -> tuple[str, bool]:
    name = params.get("name")
    slides = params.get("slides")
    if not name or not isinstance(name, str):
        return "lỗi: tham số 'name' thiếu hoặc không phải chuỗi (tên file .pptx trong deck-lab/)", False
    if not slides or not isinstance(slides, list):
        return "lỗi: tham số 'slides' thiếu hoặc không phải list (cần ít nhất 1 slide, xem inputSchema)", False
    accent = _hex_to_rgb(params.get("accent", "#0B5ED7"))

    prs = new_prs()
    for i, spec in enumerate(slides):
        kind = spec.get("kind")
        try:
            if kind == "cover":
                slide_cover(prs, spec.get("title", ""), spec.get("subtitle", ""), spec.get("footer", ""))
            elif kind == "agenda":
                slide_agenda(prs, spec.get("title", "Nội dung chính"), spec.get("items", []), accent=accent)
            elif kind == "cards":
                slide_cards(prs, spec.get("title", ""), spec.get("cards", []), accent=accent)
            elif kind == "twocol":
                slide_twocol(prs, spec.get("title", ""), spec.get("columns", []), source=spec.get("subtitle"))
            elif kind == "process":
                slide_process(prs, spec.get("title", ""), spec.get("items", []), accent=accent)
            elif kind == "barchart":
                data = [(row[0], float(row[1])) for row in spec.get("data", [])]
                slide_barchart(prs, spec.get("title", ""), data, accent=accent, source=spec.get("subtitle"))
            elif kind == "quote":
                slide_quote(prs, spec.get("lead", ""), spec.get("title", ""), spec.get("attribution", ""))
            elif kind == "closing":
                slide_closing(prs, spec.get("title", ""), spec.get("subtitle", ""))
            else:
                return f"lỗi: slide thứ {i+1} có kind {kind!r} không hợp lệ (chọn trong cover/agenda/cards/twocol/process/barchart/quote/closing)", False
        except Exception as exc:
            return f"lỗi: slide thứ {i+1} (kind={kind!r}) — {type(exc).__name__}: {exc}", False

    out_dir = ROOT / "deck-lab"
    out_dir.mkdir(exist_ok=True)
    out_path = out_dir / f"{name}.pptx"
    prs.save(str(out_path))

    from check_deck import check as deck_check
    hard, soft, n = deck_check(str(out_path))
    msg = f"Tạo {out_path.name} ({n} slide).\n"
    if hard:
        msg += "LỖI CỨNG (phải sửa):\n" + "\n".join(" - " + h for h in hard) + "\n"
    else:
        msg += "Không có lỗi cứng theo check_deck (mục 8 SKILL.md).\n"
    if soft:
        msg += f"Cảnh báo cần render xác nhận: {len(soft)} (chưa liệt kê, chạy check_deck để xem chi tiết)."
    return msg, True


def check_deck(params: dict) -> tuple[str, bool]:
    path = params.get("path")
    if not path or not isinstance(path, str):
        return "lỗi: tham số 'path' thiếu hoặc không phải chuỗi (đường dẫn .pptx)", False
    p = Path(path)
    if not p.is_absolute():
        p = ROOT / p
    if not p.exists():
        return f"lỗi: file {path!r} không tồn tại", False
    from check_deck import check
    hard, soft, n = check(str(p))
    out = [f"{p.name} ({n} slide)"]
    if hard:
        out.append("LỖI CỨNG (phải sửa trước khi báo xong):")
        out += [f"  - {h}" for h in hard]
    else:
        out.append("LỖI CỨNG: không")
    if soft:
        out.append("CẢNH BÁO (cần render + view_image xác nhận, không loại bộ):")
        out += [f"  - {s}" for s in soft]
    else:
        out.append("CẢNH BÁO: không")
    return "\n".join(out), not hard

